#!/usr/bin/env python3
"""Generate the password-change exempt route set from its registry.

Input : contracts/registries/password-change-exempt-routes.yaml
Output: internal/transport/http/api/v1/auth/password_change_exempt_gen.go

--check 只比较生成结果与现有文件，不写盘。
"""
import subprocess
import sys
from pathlib import Path

import yaml

ROOT = Path(__file__).resolve().parent.parent
REGISTRY = ROOT / "contracts/registries/password-change-exempt-routes.yaml"
OUTPUT = ROOT / "internal/transport/http/api/v1/auth/password_change_exempt_gen.go"
CHECK = "--check" in sys.argv

HEADER = (
    "// Code generated by scripts/gen_password_change_exempt.py from "
    "contracts/registries/password-change-exempt-routes.yaml; DO NOT EDIT.\n"
)


def load_routes():
    data = yaml.safe_load(REGISTRY.read_text()) or {}
    routes = []
    seen = set()
    for entry in data.get("routes") or []:
        method = str(entry.get("method") or "").strip().upper()
        path = str(entry.get("path") or "").strip()
        if not method or not path:
            raise SystemExit(f"invalid route entry: {entry!r}")
        key = f"{method} {path}"
        if key in seen:
            raise SystemExit(f"duplicate route entry: {key}")
        seen.add(key)
        routes.append(key)
    return routes


def render(routes):
    lines = [HEADER, "package auth\n", 'import "strings"\n',
             '// PasswordChangeExemptRoutes maps "METHOD path" to the exempt set.',
             "var PasswordChangeExemptRoutes = map[string]struct{}{"]
    for key in routes:
        lines.append(f'\t"{key}": {{}},')
    lines.append("}\n")
    lines.append("// PasswordChangeExempt reports whether a route bypasses the")
    lines.append("// password-change gate. OPTIONS is also allowed unconditionally by")
    lines.append("// the middleware, and {param} segments match exactly one non-empty")
    lines.append("// path segment.")
    lines.append("func PasswordChangeExempt(method, path string) bool {")
    lines.append("\tmethod = strings.ToUpper(strings.TrimSpace(method))")
    lines.append('\tif _, ok := PasswordChangeExemptRoutes[method+" "+path]; ok {')
    lines.append("\t\treturn true")
    lines.append("\t}")
    lines.append("\tfor route := range PasswordChangeExemptRoutes {")
    lines.append("\t\tparts := strings.SplitN(route, \" \", 2)")
    lines.append('\t\tif len(parts) != 2 || parts[0] != method || !strings.Contains(parts[1], "{") {')
    lines.append("\t\t\tcontinue")
    lines.append("\t\t}")
    lines.append("\t\tif matchPasswordChangeExemptPattern(parts[1], path) {")
    lines.append("\t\t\treturn true")
    lines.append("\t\t}")
    lines.append("\t}")
    lines.append("\treturn false")
    lines.append("}\n")
    lines.append("func matchPasswordChangeExemptPattern(pattern, path string) bool {")
    lines.append('\tpatternSegments := strings.Split(strings.Trim(pattern, "/"), "/")')
    lines.append('\tpathSegments := strings.Split(strings.Trim(path, "/"), "/")')
    lines.append("\tif len(patternSegments) != len(pathSegments) {")
    lines.append("\t\treturn false")
    lines.append("\t}")
    lines.append("\tfor i, segment := range patternSegments {")
    lines.append('\t\tif strings.HasPrefix(segment, "{") && strings.HasSuffix(segment, "}") {')
    lines.append("\t\t\tif pathSegments[i] == \"\" {")
    lines.append("\t\t\t\treturn false")
    lines.append("\t\t\t}")
    lines.append("\t\t\tcontinue")
    lines.append("\t\t}")
    lines.append("\t\tif segment != pathSegments[i] {")
    lines.append("\t\t\treturn false")
    lines.append("\t\t}")
    lines.append("\t}")
    lines.append("\treturn true")
    lines.append("}\n")
    return "\n".join(lines)


def gofmt(text):
    result = subprocess.run(["gofmt"], input=text.encode(), capture_output=True, check=True)
    return result.stdout.decode()


def main():
    routes = load_routes()
    rendered = gofmt(render(routes))
    if CHECK:
        if not OUTPUT.exists():
            print(f"FAIL: {OUTPUT} is missing")
            return 1
        if OUTPUT.read_text() != rendered:
            print(f"FAIL: {OUTPUT} differs from registry")
            return 1
        print(f"PASS: {OUTPUT} matches registry")
        return 0
    OUTPUT.write_text(rendered)
    print(f"generated {OUTPUT} ({len(routes)} routes)")
    return 0


if __name__ == "__main__":
    sys.exit(main())
